use super::benchmark_result::BenchmarkResult;
use super::optimizer_kind::OptimizerKind;
use super::types::BenchmarkConfig;
use math_audio_optimisation::{DEConfigBuilder, LShadeConfig, Strategy};
use ndarray::Array1;
use std::time::Duration;

pub(super) fn build_de_config(
    config: &BenchmarkConfig,
) -> Result<math_audio_optimisation::DEConfig, Box<dyn std::error::Error>> {
    Ok(DEConfigBuilder::new()
        .seed(config.seed)
        .maxiter(config.maxiter)
        .popsize(config.popsize)
        .strategy(lshade_strategy(config))
        .recombination(config.recombination)
        .lshade(LShadeConfig::default())
        .build()?)
}

pub(super) fn lshade_strategy(config: &BenchmarkConfig) -> Strategy {
    if matches!(
        config.strategy,
        Strategy::Best1Exp
            | Strategy::Rand1Exp
            | Strategy::Rand2Exp
            | Strategy::CurrentToBest1Exp
            | Strategy::Best2Exp
            | Strategy::RandToBest1Exp
            | Strategy::AdaptiveExp
            | Strategy::LShadeExp
    ) {
        Strategy::LShadeExp
    } else {
        Strategy::LShadeBin
    }
}

pub(super) fn solution_within_tolerances(
    config: &BenchmarkConfig,
    x: &Array1<f64>,
    fun_value: f64,
) -> bool {
    fun_value < config.fun_tolerance
        && x.iter()
            .zip(config.expected_optimum.iter())
            .all(|(actual, expected)| (actual - expected).abs() < config.position_tolerance)
}

pub(super) fn validate_solution(
    config: &BenchmarkConfig,
    optimizer: OptimizerKind,
    x: &Array1<f64>,
    fun_value: f64,
    nfev: usize,
    duration: Duration,
) -> BenchmarkResult {
    let fun_ok = fun_value < config.fun_tolerance;

    let position_errors: Vec<f64> = x
        .iter()
        .zip(config.expected_optimum.iter())
        .map(|(actual, expected)| (actual - expected).abs())
        .collect();

    let position_ok = position_errors
        .iter()
        .all(|&err| err < config.position_tolerance);

    let success = fun_ok && position_ok;
    let error_message = if !success {
        let mut msgs = Vec::new();
        if !fun_ok {
            msgs.push(format!(
                "fun value {:.6e} >= {:.2e}",
                fun_value, config.fun_tolerance
            ));
        }
        if !position_ok {
            let max_err = position_errors.iter().fold(0.0f64, |a, &b| a.max(b));
            msgs.push(format!(
                "max position error {:.6} >= {:.2}",
                max_err, config.position_tolerance
            ));
        }
        Some(msgs.join(", "))
    } else {
        None
    };

    BenchmarkResult {
        name: config.name.clone(),
        optimizer,
        success,
        fun_value,
        fun_tolerance: config.fun_tolerance,
        position_errors,
        position_tolerance: config.position_tolerance,
        nfev,
        duration,
        error_message,
    }
}

pub(super) fn failed_result(
    config: &BenchmarkConfig,
    optimizer: OptimizerKind,
    duration: Duration,
    error_message: String,
) -> BenchmarkResult {
    BenchmarkResult {
        name: config.name.clone(),
        optimizer,
        success: false,
        fun_value: f64::INFINITY,
        fun_tolerance: config.fun_tolerance,
        position_errors: vec![f64::INFINITY],
        position_tolerance: config.position_tolerance,
        nfev: 0,
        duration,
        error_message: Some(error_message),
    }
}
